 function render(name,size=20,cls='f-icon',weight='bold'){
  if(!Object.prototype.hasOwnProperty.call(paths,name))throw new Error('Unknown icon: '+name);
  const n=Number(size);
  if(!Number.isFinite(n)||n<8||n>128)throw new Error('Invalid icon size');
  const cl=String(cls).replace(/[^\w\s-]/g,''),key=weight==='fill'&&paths[name+':fill']?name+':fill':name;
  return `<svg class="${cl}" data-icon="${name}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="${n}" height="${n}" fill="currentColor" aria-hidden="true">${paths[key]}</svg>`;
 }
